import base64
import json
import os
from typing import Any, Dict, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


STANDARD_SCHEMA = {
    "vendor_name": None,
    "invoice_number": None,
    "invoice_date": None,
    "due_date": None,
    "currency": None,
    "subtotal": None,
    "tax": None,
    "total": None,
    "payment_terms": None,
    "purchase_order": None,
    "bill_to": {
        "name": None,
        "address": None,
    },
    "ship_to": {
        "name": None,
        "address": None,
    },
    "line_items": [],
    "raw_provider_response": None,
}


def _to_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value).strip()
    if not text:
        return None
    filtered = "".join(ch for ch in text if ch.isdigit() or ch in {".", "-", ","})
    filtered = filtered.replace(",", "")
    try:
        return float(filtered)
    except ValueError:
        return None


def _to_str(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        s = value.strip()
        return s or None
    for attr in ("content", "value", "text", "date", "amount"):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if v is not None:
                s = str(v).strip()
                return s or None
    return str(value).strip() or None


def _address_to_str(addr: Any) -> Optional[str]:
    if addr is None:
        return None
    if isinstance(addr, str):
        s = addr.strip()
        return s or None
    parts = []
    for key in ("street_address", "street", "house_number", "city", "state", "postal_code", "country_region", "postalcode"):
        v = getattr(addr, key, None)
        if v:
            parts.append(str(v).strip())
    if parts:
        return ", ".join([p for p in parts if p])
    return _to_str(addr)


def _extract_field(result: Any, *names: str) -> Any:
    for name in names:
        if hasattr(result, name):
            val = getattr(result, name)
            if val is not None:
                return val
    return None


def normalize_expense_fields(extracted: Dict[str, Any]) -> Dict[str, Any]:
    schema = json.loads(json.dumps(STANDARD_SCHEMA))
    schema["vendor_name"] = _to_str(extracted.get("vendor_name") or extracted.get("merchant_name") or extracted.get("supplier_name"))
    schema["invoice_number"] = _to_str(extracted.get("invoice_number") or extracted.get("document_number") or extracted.get("invoice_id"))
    schema["invoice_date"] = _to_str(extracted.get("invoice_date") or extracted.get("issue_date"))
    schema["due_date"] = _to_str(extracted.get("due_date"))
    schema["currency"] = _to_str(extracted.get("currency") or extracted.get("currency_code"))
    schema["subtotal"] = _to_float(extracted.get("subtotal") or extracted.get("net_amount"))
    schema["tax"] = _to_float(extracted.get("tax") or extracted.get("tax_amount"))
    schema["total"] = _to_float(extracted.get("total") or extracted.get("amount_due") or extracted.get("grand_total"))
    schema["payment_terms"] = _to_str(extracted.get("payment_terms"))
    schema["purchase_order"] = _to_str(extracted.get("purchase_order") or extracted.get("po_number"))
    bill_to = extracted.get("bill_to") or {}
    ship_to = extracted.get("ship_to") or {}
    schema["bill_to"]["name"] = _to_str(bill_to.get("name") if isinstance(bill_to, dict) else bill_to)
    schema["bill_to"]["address"] = _address_to_str(bill_to.get("address") if isinstance(bill_to, dict) else None)
    schema["ship_to"]["name"] = _to_str(ship_to.get("name") if isinstance(ship_to, dict) else ship_to)
    schema["ship_to"]["address"] = _address_to_str(ship_to.get("address") if isinstance(ship_to, dict) else None)

    line_items = extracted.get("line_items") or extracted.get("items") or []
    normalized_items = []
    if isinstance(line_items, list):
        for item in line_items:
            if isinstance(item, dict):
                normalized_items.append(
                    {
                        "description": _to_str(item.get("description") or item.get("name") or item.get("item")),
                        "quantity": _to_float(item.get("quantity")),
                        "unit_price": _to_float(item.get("unit_price") or item.get("price")),
                        "amount": _to_float(item.get("amount") or item.get("total")),
                        "tax": _to_float(item.get("tax")),
                    }
                )
            else:
                normalized_items.append({"description": _to_str(item), "quantity": None, "unit_price": None, "amount": None, "tax": None})
    schema["line_items"] = normalized_items
    schema["raw_provider_response"] = extracted.get("raw_provider_response")
    return schema


def extract_expense_fields(document: Any, content_type: Optional[str] = None) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]
    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    if isinstance(document, str) and os.path.isfile(document):
        with open(document, "rb") as f:
            data = f.read()
    elif isinstance(document, (bytes, bytearray)):
        data = bytes(document)
    elif isinstance(document, str):
        data = base64.b64decode(document)
    else:
        raise TypeError("document must be a file path, bytes, or base64-encoded string")

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=data,
        content_type=content_type or "application/pdf",
    )
    result = poller.result()

    invoices = getattr(result, "documents", None) or []
    if not invoices:
        normalized = json.loads(json.dumps(STANDARD_SCHEMA))
        normalized["raw_provider_response"] = result
        return normalized

    invoice = invoices[0]
    fields = getattr(invoice, "fields", {}) or {}

    extracted = {
        "vendor_name": _to_str(_extract_field(fields.get("VendorName"), "content", "value", "value_string")),
        "invoice_number": _to_str(_extract_field(fields.get("InvoiceId"), "content", "value", "value_string")),
        "invoice_date": _to_str(_extract_field(fields.get("InvoiceDate"), "content", "value", "value_date")),
        "due_date": _to_str(_extract_field(fields.get("DueDate"), "content", "value", "value_date")),
        "currency": _to_str(
            _extract_field(
                fields.get("InvoiceTotal"),
                "currency_code",
                "currency",
            )
        ),
        "subtotal": _to_float(_extract_field(fields.get("SubTotal"), "value", "content")),
        "tax": _to_float(_extract_field(fields.get("TotalTax"), "value", "content")),
        "total": _to_float(_extract_field(fields.get("InvoiceTotal"), "value", "content")),
        "payment_terms": _to_str(_extract_field(fields.get("PaymentTerms"), "content", "value")),
        "purchase_order": _to_str(_extract_field(fields.get("PurchaseOrder"), "content", "value")),
        "bill_to": {
            "name": _to_str(_extract_field(fields.get("BillingAddressRecipient"), "content", "value")),
            "address": _address_to_str(_extract_field(fields.get("BillingAddress"), "content", "value")),
        },
        "ship_to": {
            "name": _to_str(_extract_field(fields.get("ShippingAddressRecipient"), "content", "value")),
            "address": _address_to_str(_extract_field(fields.get("ShippingAddress"), "content", "value")),
        },
        "line_items": [],
        "raw_provider_response": result,
    }

    for item in getattr(invoice, "items", []) or []:
        item_fields = getattr(item, "fields", {}) or {}
        extracted["line_items"].append(
            {
                "description": _to_str(_extract_field(item_fields.get("Description"), "content", "value")),
                "quantity": _to_float(_extract_field(item_fields.get("Quantity"), "value", "content")),
                "unit_price": _to_float(_extract_field(item_fields.get("UnitPrice"), "value", "content")),
                "amount": _to_float(_extract_field(item_fields.get("Amount"), "value", "content")),
                "tax": _to_float(_extract_field(item_fields.get("Tax"), "value", "content")),
            }
        )

    normalized = normalize_expense_fields(extracted)
    if isinstance(result, dict):
        normalized["raw_provider_response"] = result
    else:
        normalized["raw_provider_response"] = {
            "documents": len(getattr(result, "documents", []) or []),
            "content": getattr(result, "content", None),
        }
    return normalized
